//! Experimental diagnostic verification of compiler-checked scalar loan events.
//!
//! Events are generated by FnCx while type-checking source, not supplied by
//! users. Nevertheless this verifier is NOT an independently proven
//! source/typed-IR/emitted-Wasm completeness witness. It must never override
//! existing borrow checker rejections or permit new runtime/AOT behavior.
//! A bounded, straight-line, nonescaping scalar profile is supported here.
use std::collections::{BTreeMap, BTreeSet};

use crate::ast::Type;
use crate::check::{TExpr, TFunc, TProgram, TStmt, TE};
use crate::diag::{Diagnostic, Pos};

const MAX_FUNCTIONS: usize = 256;
const MAX_POINTS: usize = 4096;
const MAX_LOANS: usize = 1024;
const MAX_WORK: usize = 100_000;
const MAX_DEPTH: usize = 128;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Event {
    Issue { loan_id: u32, owner_slot: u32, exclusive: bool },
    Use { loan_id: u32, owner_slot: u32, write: bool },
    End { loan_id: u32, owner_slot: u32, scope_exit: bool },
    Read { owner_slot: u32, origin: u32 },
    Write { owner_slot: u32, new_origin: u32 },
    Return,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Point {
    pub id: u32,
    pub event: Event,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Function {
    pub index: u32,
    pub name: String,
    pub points: Vec<Point>,
    pub possible_trap: bool,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Census {
    pub contract: &'static str,
    pub functions: Vec<Function>,
}
pub const CONTRACT: &str = "atto-typed-scalar-loan-events-v1";

#[derive(Clone, Copy, Debug)]
struct Loan {
    slot: u32,
    exclusive: bool,
    used: bool,
}
fn unsupported(message: &'static str) -> Diagnostic {
    Diagnostic::new(Pos::default(), "E_LOAN_CENSUS_UNSUPPORTED", message)
}
fn invalid(message: &'static str) -> Diagnostic {
    Diagnostic::new(Pos::default(), "E_LOAN_CENSUS_INVALID", message)
}
fn budget(message: &'static str) -> Diagnostic {
    Diagnostic::new(Pos::default(), "E_LOAN_CENSUS_BUDGET", message)
}
fn scalar(ty: Type) -> bool {
    matches!(ty, Type::Int | Type::Bool | Type::Float)
}
struct Verifier {
    points: Vec<Point>,
    issued: BTreeSet<u32>,
    active: BTreeMap<u32, Loan>,
    origins: BTreeMap<u32, u32>,
    next_origin: u32,
    slots: u32,
    work: usize,
    pending_write: Option<(u32, u32)>,
    returned: bool,
    possible_trap: bool,
}
impl Verifier {
    fn charge(&mut self, depth: usize) -> Result<(), Diagnostic> {
        self.work = self.work.checked_add(1).ok_or_else(|| budget("work overflow"))?;
        if self.work > MAX_WORK || depth > MAX_DEPTH {
            return Err(budget("loan event or typed-expression budget exceeded"));
        }
        Ok(())
    }
    fn push(&mut self, event: Event) -> Result<(), Diagnostic> {
        if self.points.len() >= MAX_POINTS {
            return Err(budget("too many typed loan/event points"));
        }
        self.points.push(Point {
            id: self.points.len() as u32 + 1,
            event,
        });
        Ok(())
    }
    fn reads(&mut self, value: &TE, depth: usize) -> Result<(), Diagnostic> {
        self.charge(depth)?;
        if !scalar(value.ty) {
            return Err(unsupported("nonscalar expression requires alias/heap provenance"));
        }
        match &value.e {
            TExpr::I64(_) | TExpr::F64(_) | TExpr::Bool(_) => Ok(()),
            TExpr::Local(slot) => {
                if *slot >= self.slots {
                    return Err(invalid("typed scalar load outside local inventory"));
                }
                let origin = *self
                    .origins
                    .get(slot)
                    .ok_or_else(|| invalid("typed local read before definition"))?;
                // An exclusive alias may read its owner's actual scalar slot;
                // the compiler emits a preceding source-checked LoanUse marker.
                // This alone does NOT prove that every emitted read is marked.
                self.push(Event::Read { owner_slot: *slot, origin })
            }
            TExpr::Neg(e) | TExpr::FNeg(e) => {
                self.possible_trap = true;
                self.reads(e, depth + 1)
            }
            TExpr::Not(e) | TExpr::IntToFloat(e) => self.reads(e, depth + 1),
            TExpr::Bin(_, left, right) => {
                // Conservatively record possible checked-arithmetic traps.
                self.possible_trap = true;
                self.reads(left, depth + 1)?;
                self.reads(right, depth + 1)
            }
            TExpr::Builtin(_, left, right) => {
                self.reads(left, depth + 1)?;
                self.reads(right, depth + 1)
            }
            _ => Err(unsupported("control-flow, call, print, heap or actor expression unmodeled")),
        }
    }
    fn visit(&mut self, stmt: &TStmt, depth: usize) -> Result<(), Diagnostic> {
        self.charge(depth)?;
        if self.returned {
            return Err(invalid("typed events occur after terminal return"));
        }
        match stmt {
            TStmt::ScalarBorrowIssue {
                loan_id,
                owner_slot,
                exclusive,
                alias,
            } => {
                if *loan_id == 0
                    || alias.is_empty()
                    || *owner_slot >= self.slots
                    || self.issued.len() >= MAX_LOANS
                    || !self.issued.insert(*loan_id)
                {
                    return Err(invalid("invalid, reused, or excessive checked loan ID"));
                }
                if self.active.values().any(|l| l.slot == *owner_slot && (l.exclusive || *exclusive)) {
                    return Err(invalid("overlapping shared/exclusive loan origins"));
                }
                if !self.origins.contains_key(owner_slot) {
                    return Err(invalid("loan owner has no initialized scalar origin"));
                }
                self.active.insert(
                    *loan_id,
                    Loan {
                        slot: *owner_slot,
                        exclusive: *exclusive,
                        used: false,
                    },
                );
                self.push(Event::Issue {
                    loan_id: *loan_id,
                    owner_slot: *owner_slot,
                    exclusive: *exclusive,
                })
            }
            TStmt::ScalarBorrowUse {
                loan_id,
                owner_slot,
                write,
            } => {
                let loan = self
                    .active
                    .get_mut(loan_id)
                    .ok_or_else(|| invalid("use of unissued, expired or ended loan"))?;
                if loan.slot != *owner_slot || (*write && !loan.exclusive) {
                    return Err(invalid("loan use owner or exclusive write capability mismatch"));
                }
                if self.pending_write.is_some() {
                    return Err(invalid("unpaired exclusive write-through marker"));
                }
                loan.used = true;
                if *write {
                    self.pending_write = Some((*loan_id, *owner_slot));
                }
                self.push(Event::Use {
                    loan_id: *loan_id,
                    owner_slot: *owner_slot,
                    write: *write,
                })
            }
            TStmt::ScalarBorrowEnd {
                loan_id,
                owner_slot,
                scope_exit,
            } => {
                if self.pending_write.is_some() {
                    return Err(invalid("write-through marker lacks its owner assignment"));
                }
                let loan = self
                    .active
                    .remove(loan_id)
                    .ok_or_else(|| invalid("end of nonexistent or already ended loan"))?;
                if loan.slot != *owner_slot || (!*scope_exit && !loan.used) {
                    return Err(invalid("loan end owner or NLL prior-use evidence mismatch"));
                }
                self.push(Event::End {
                    loan_id: *loan_id,
                    owner_slot: *owner_slot,
                    scope_exit: *scope_exit,
                })
            }
            TStmt::Set(slot, value) => {
                if *slot >= self.slots {
                    return Err(invalid("typed scalar set outside local inventory"));
                }
                self.reads(value, depth + 1)?;
                let matching_writer = if let Some((loan_id, writer_slot)) = self.pending_write.take() {
                    if writer_slot != *slot || !self.active.get(&loan_id).is_some_and(|l| l.slot == *slot && l.exclusive) {
                        return Err(invalid("write-through event not paired with its owner set"));
                    }
                    Some(loan_id)
                } else {
                    None
                };
                for (&loan_id, loan) in &self.active {
                    if loan.slot == *slot && Some(loan_id) != matching_writer {
                        return Err(invalid("owner write conflicts with live loan"));
                    }
                }
                if self.next_origin as usize > MAX_WORK {
                    return Err(budget("scalar origin generation exhausted"));
                }
                let new_origin = self.next_origin;
                self.next_origin += 1;
                self.origins.insert(*slot, new_origin);
                self.push(Event::Write {
                    owner_slot: *slot,
                    new_origin,
                })
            }
            TStmt::Expr(expr) => {
                if self.pending_write.is_some() {
                    return Err(invalid("exclusive write-through does not lead to an owner set"));
                }
                self.reads(expr, depth + 1)
            }
            TStmt::Return(value) => {
                if self.pending_write.is_some() {
                    return Err(invalid("exclusive write-through does not lead to owner set"));
                }
                if let Some(value) = value {
                    self.reads(value, depth + 1)?;
                }
                // Source checker independently prevents borrowed-reference
                // escape; function return closes remaining scalar loans.
                self.push(Event::Return)?;
                self.returned = true;
                self.active.clear();
                Ok(())
            }
            TStmt::Block(body) => {
                for child in body {
                    self.visit(child, depth + 1)?;
                }
                Ok(())
            }
            _ => Err(unsupported("nonlinear CFG, suspension, exception or memory effect unmodeled")),
        }
    }
}
fn verify(index: usize, func: &TFunc) -> Result<Function, Diagnostic> {
    if !scalar(func.ret) && func.ret != Type::Void {
        return Err(unsupported("borrow census requires scalar return type"));
    }
    if func.params.iter().chain(func.locals.iter()).any(|&ty| !scalar(ty)) {
        return Err(unsupported("borrow census requires scalar local storage"));
    }
    let slots = func
        .params
        .len()
        .checked_add(func.locals.len())
        .ok_or_else(|| budget("local count overflow"))?;
    if slots > MAX_LOANS {
        return Err(budget("scalar local count exceeds budget"));
    }
    let mut state = Verifier {
        points: Vec::new(),
        issued: BTreeSet::new(),
        active: BTreeMap::new(),
        origins: BTreeMap::new(),
        next_origin: func.params.len() as u32 + 1,
        slots: slots as u32,
        work: 0,
        pending_write: None,
        returned: false,
        possible_trap: false,
    };
    for slot in 0..func.params.len() as u32 {
        state.origins.insert(slot, slot + 1);
    }
    for stmt in &func.body {
        state.visit(stmt, 0)?;
    }
    if !state.returned {
        return Err(unsupported("missing explicit terminal return or unmodeled fallthrough"));
    }
    Ok(Function {
        index: index as u32,
        name: func.name.clone(),
        points: state.points,
        possible_trap: state.possible_trap,
    })
}
/// Model verdict on the exact checked typed program, never a codegen gate.
/// Failure is diagnostic-only; normal `compile` retains existing admission.
pub fn from_checked_program(program: &TProgram) -> Result<Census, Diagnostic> {
    if program.funcs.is_empty()
        || program.funcs.len() > MAX_FUNCTIONS
        || !program.generators.is_empty()
        || !program.actors.is_empty()
        || program.heap
        || program.guest_eh
    {
        return Err(unsupported("actor, generator, heap or exception profile not modeled"));
    }
    let mut functions = Vec::with_capacity(program.funcs.len());
    for (index, func) in program.funcs.iter().enumerate() {
        functions.push(verify(index, func)?);
    }
    Ok(Census {
        contract: CONTRACT,
        functions,
    })
}
